async function piAirbnbMarkAwaitingOtp(job) {
  // Request email OTP at most once — a second Prefer clicks the same control and emails another code
  if ((await piAirbnbOtpDeliveryKind(job.page)) !== 'email') {
    await piAirbnbPreferEmailDelivery(job.page);
    try { await job.page.waitForTimeout(2000); } catch (e) {}
  }
  job.status = 'awaiting_otp';
  await piAirbnbSnapshotOtpMeta(job);
  job.hint = (job.hint || 'Check host email for the code.') + ' Use the newest email only; do not Resend unless the code expired.';
}

